if(!function_exists('curl_init') && !ini_get('allow_url_fopen')) $pk_warn[] = 'PHP can’t fetch web pages (<b>curl</b> is off and <b>allow_url_fopen</b> is off), so live gold prices can’t be looked up. Turn on the <b>curl</b> extension.';
